const readline = require('readline');

function main() {
    let input = '';
    process.stdin.on('data', (chunk) => { input += chunk; });
    process.stdin.on('end', () => {
        const lines = input.trim().split('\n');
        if (lines.length === 0 || lines[0] === '') { console.log(0); return; }
        const first = lines[0].trim().split(/\s+/).map(Number);
        const S = first[0], T = first[1], P = first[2];
        const heights = lines[1].trim().split(/\s+/).map(Number);

        const adj = Array.from({ length: S + 1 }, () => []);
        for (let i = 0; i < T; i++) {
            const [I, J] = lines[2 + i].trim().split(/\s+/).map(Number);
            adj[I].push(J);
            adj[J].push(I);
        }

        const visited = new Array(S + 1).fill(false);
        const stack = [P];
        visited[P] = true;
        let count = 0;

        while (stack.length > 0) {
            const u = stack.pop();
            for (const v of adj[u]) {
                if (!visited[v] && heights[u - 1] > heights[v - 1]) {
                    visited[v] = true;
                    count++;
                    stack.push(v);
                }
            }
        }

        console.log(count);
    });
}

main();
